        earth: { kid: 'À distância da Terra, 150 milhões de quilómetros, um metro quadrado virado para o Sol recebe 1361 watts de luz acima do ar. Todas as células são medidas por este número.', sci: 'A constante solar: 1361 W/m² a 1 UA (149,6 milhões de km), acima da atmosfera. As células são classificadas por ela.' },
        mars: { kid: 'Marte está uma vez e meia mais longe, por isso a luz é só cerca de 43 partes em 100 da nossa: cerca de 590 watts em cada metro quadrado. Os robôs Spirit e Opportunity aterraram aqui em 2004, com células como estas. Toca no robô!', sci: 'Marte, 1,524 UA: cerca de 590 W/m² (de uns 490 a 715 ao longo do seu ano elíptico). O Spirit e o Opportunity (2004) levavam painéis de GaInP/GaAs/Ge.' },
        jupiter: { kid: 'Júpiter está cinco vezes mais longe do que a Terra, por isso a luz é vinte e cinco vezes mais fraca: só cerca de 50 watts por metro quadrado. Uma asa que alimenta um satélite grande perto da Terra mal acenderia umas lâmpadas aqui.', sci: 'Júpiter, 5,2 UA: cerca de 50 W/m², 3,7% do da Terra. As sondas aqui levam painéis enormes ou uma fonte de energia radioativa.' },
        slide: { kid: 'A {d} vezes a distância da Terra há {w} watts em cada metro quadrado.', sci: 'd = {d} UA: S = {w} W/m²; a asa de exemplo faz {p}.' },
        rover: { kid: 'O Spirit e o Opportunity aterraram em Marte em janeiro de 2004 e andavam à luz do Sol. O pó cobria-lhes as asas e, de vez em quando, o vento levava-o. O Opportunity trabalhou quase quinze anos; foi feito para três meses.', sci: 'Spirit e Opportunity (janeiro de 2004): painéis de GaInP/GaAs/Ge, no início cerca de 140 W durante umas quatro horas por sol, a descer com o pó e as estações. Previsto para 90 sóis, o Opportunity durou até 2018.' },
